function conScrollFermo(fn) {
  const y = window.scrollY || window.pageYOffset || 0;
  const ripristina = () => { try { window.scrollTo(0, y); } catch {  } };
  let r;
  try { r = fn(); } catch (e) { requestAnimationFrame(ripristina); throw e; }
  if (r && typeof r.then === 'function') { r.then(ripristina, ripristina); return r; }
  requestAnimationFrame(ripristina);
  return r;
}

function render() {

  const _syRender = (stato && stato.user) ? (window.scrollY || 0) : 0;
  renderAreaUtente();
  const navTop = document.getElementById('nav-top');
  const navDrawer = document.getElementById('nav-drawer');
  const svuotaNav = () => { if (navTop) navTop.innerHTML = ''; if (navDrawer) navDrawer.innerHTML = ''; };

  document.body.classList.toggle('vetrina', !stato.user);

  if (!stato.user) {
    document.body.classList.remove('con-nav');
    svuotaNav();
    renderHero();
    applicaTema();
    return;
  }

  let html = '';
  const st = stato.streamer;
  const conPiattaforma = st?.status === 'approved';

  if (!st) {
    html += vistaRichiesta();
  } else if (st.status === 'pending') {
    html += vistaPending();
  } else if (st.status === 'disabled') {
    html += vistaDisabilitato();
  } else if (st.status === 'approved') {
    html += vistaPiattaforma();
  }

  if (stato.isAdmin && !conPiattaforma) html += `<hr class="separatore">${vistaAdminContenuto()}`;

  app.innerHTML = html;

  document.body.classList.toggle('con-nav', conPiattaforma);
  if (navTop) navTop.innerHTML = conPiattaforma ? navTopHtml() : '';
  if (navDrawer) navDrawer.innerHTML = conPiattaforma ? navDrawerHtml() : '';
  aggiornaTestataPagina();

  if (conPiattaforma) attivaPiattaforma();
  if (stato.isAdmin) { caricaTabellaAdmin(); caricaSalute(); caricaBackup(); caricaAnima(); caricaLLM(); caricaVita(); caricaEcosistema(); }

  try {
    if (conPiattaforma && new URLSearchParams(location.search).get('benvenuto') === '1') mostraBenvenuto();
  } catch {  }

  if (conPiattaforma) document.querySelectorAll('.pannello-scheda').forEach((p) => rendiCartePieghevoli(p, p.dataset.scheda));
  rivelaCarte();

  if (_syRender) requestAnimationFrame(() => { try { window.scrollTo(0, _syRender); } catch {  } });
}

const _menoMoto = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);

let _morphDa = null;
document.addEventListener('click', (ev) => {
  const b = ev.target && ev.target.closest ? ev.target.closest('[data-scheda]') : null;
  _morphDa = (b && b.dataset.scheda) ? b : null;
}, true);

let _morphEl = null;
function morphDa(el) {
  const app = document.getElementById('app');
  if (_morphEl && _morphEl !== el) { try { _morphEl.style.viewTransitionName = ''; } catch {  } }
  _morphEl = el || null;
  if (_morphEl) {
    if (app) app.style.viewTransitionName = 'none';
    try { _morphEl.style.viewTransitionName = 'contenuto'; } catch {  }
  } else if (app) app.style.viewTransitionName = '';
}

function transizione(fn) {
  const drawer = window.matchMedia && window.matchMedia('(max-width: 1200px)').matches;
  if (_menoMoto || drawer || !document.startViewTransition) { fn(); return { finished: Promise.resolve() }; }
  return document.startViewTransition(fn);
}

let _rivObs = null;
function _osservatore() {
  if (!_rivObs) {
    _rivObs = new IntersectionObserver((voci) => {
      for (const v of voci) if (v.isIntersecting) { v.target.classList.add('dentro'); _rivObs.unobserve(v.target); }
    }, { threshold: 0.05, rootMargin: '0px 0px -6% 0px' });
  }
  return _rivObs;
}

function preparaCarte(scope = document) {
  if (_menoMoto) return;
  for (const c of scope.querySelectorAll('.carta')) {
    c.classList.remove('dentro');
    c.classList.add('rivela');
  }
}

function avviaComparsa(sezioni) {
  const t = document.getElementById('pagina-testata');
  if (t) {
    t.classList.remove('entra');
    void t.offsetWidth;
    t.classList.add('entra');
    t.classList.remove('pronta');
  }
  (sezioni || []).forEach((p) => rivelaCarte(p));
}

function armaComparsa() {
  const t = document.getElementById('pagina-testata');
  if (!t || _menoMoto) return;
  t.classList.remove('entra');
  t.classList.add('pronta');
  setTimeout(() => {
    if (t.classList.contains('pronta') && !t.classList.contains('entra')) avviaComparsa([]);
  }, 1400);
}

function rivelaCarte(scope = document) {
  const carte = [...scope.querySelectorAll('.carta')];
  if (_menoMoto) { carte.forEach((c) => c.classList.add('rivela', 'dentro')); return; }
  const obs = _osservatore();
  let inVista = 0;
  for (const c of carte) {
    c.classList.remove('dentro');
    c.classList.add('rivela');
    const r = c.getBoundingClientRect();
    const visibile = r.top < window.innerHeight * 0.92;

    c.style.setProperty('--rev-delay', visibile ? 230 + Math.min(inVista++, 5) * 55 + 'ms' : '0ms');
    obs.observe(c);
  }
}

const _icoChevron = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>';

function _chiaveCarta(scheda, titolo) {
  return 'carta:' + scheda + ':' + String(titolo || '').toLowerCase().replace(/\s+/g, ' ').trim().slice(0, 50);
}
function _cartaChiusa(k) { try { return localStorage.getItem(k) === '0'; } catch { return false; } }
function _ricordaCarta(k, aperta) { try { localStorage.setItem(k, aperta ? '1' : '0'); } catch {  } }

function _riassuntoCarta(corpo) {
  const p = corpo.querySelector('p');
  const t = (p?.textContent || '').replace(/\s+/g, ' ').trim();
  if (!t) return '';
  const primaFrase = t.split(/(?<=[.!?])\s/)[0] || t;
  return primaFrase.length > 120 ? primaFrase.slice(0, 117).trimEnd() + '…' : primaFrase;
}

function rendiCartePieghevoli(scope, scheda) {
  for (const carta of scope.querySelectorAll('.carta')) {
    if (carta.classList.contains('pieghevole')) continue;
    if (carta.tagName === 'DETAILS') continue;
    if (carta.classList.contains('gira-telefono')) continue;
    const h2 = carta.querySelector(':scope > h2');
    if (!h2) continue;

    const resto = [];
    for (let n = h2.nextSibling; n; n = n.nextSibling) resto.push(n);
    if (!resto.length) continue;

    const corpo = document.createElement('div');
    corpo.className = 'carta-corpo';
    const dentro = document.createElement('div');
    dentro.className = 'carta-corpo-in';
    resto.forEach((n) => dentro.appendChild(n));
    corpo.appendChild(dentro);
    carta.appendChild(corpo);

    const chev = document.createElement('span');
    chev.className = 'carta-chevron';
    chev.innerHTML = _icoChevron;
    h2.appendChild(chev);
    h2.setAttribute('role', 'button');
    h2.setAttribute('tabindex', '0');

    const testo = _riassuntoCarta(dentro);
    if (testo) {
      const r = document.createElement('p');
      r.className = 'carta-riassunto';
      r.textContent = testo;
      h2.insertAdjacentElement('afterend', r);
    }

    carta.classList.add('pieghevole');
    const k = _chiaveCarta(scheda || schedaAttiva, h2.textContent);
    carta.dataset.ck = k;
    if (_cartaChiusa(k)) carta.classList.add('chiusa');
    h2.setAttribute('aria-expanded', carta.classList.contains('chiusa') ? 'false' : 'true');
  }
}

function _piegaCarta(carta, aperta) {
  carta.classList.toggle('chiusa', !aperta);
  carta.querySelector(':scope > h2')?.setAttribute('aria-expanded', aperta ? 'true' : 'false');
  if (carta.dataset.ck) _ricordaCarta(carta.dataset.ck, aperta);
}

function barraCarteHtml() {
  return `<div class="carte-ctrl">
    <button type="button" class="btn secondario mini" data-carte="apri">${L('Apri tutto', 'Expand all', 'Abrir todo')}</button>
    <button type="button" class="btn secondario mini" data-carte="chiudi">${L('Riduci tutto', 'Collapse all', 'Reducir todo')}</button>
    <span class="suggerimento">${tocco()
      ? L('Tocca il titolo di una scheda per aprirla o ridurla.', 'Tap a card’s title to expand or collapse it.', 'Toca el título de una tarjeta para abrirla o reducirla.')
      : L('Clicca il titolo di una scheda per aprirla o ridurla.', 'Click a card’s title to expand or collapse it.', 'Haz clic en el título de una tarjeta para abrirla o reducirla.')}</span>
  </div>`;
}

function renderAreaUtente() {
  const areaMob = document.getElementById('area-utente-mob');
  if (!stato.user) { if (areaUtente) areaUtente.innerHTML = ''; if (areaMob) areaMob.innerHTML = ''; return; }

  const canali = stato.mieiCanali || [];
  const ident = esc(stato.identitaDisplay || stato.user.identitaDisplay || stato.user.modDisplay || stato.user.display || 'tu');
  const attuale = stato.user.login;
  const etichetta = (c) => (c.role === 'proprietario' ? 'il mio canale @' : 'moderi @') + c.display;

  let centro = '';
  if (canali.length > 1) {
    const chevron = '<svg class="sc-freccia" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>';
    const check = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg>';
    const corr = canali.find((c) => c.canale === attuale) || canali[0];
    centro = `<div class="switch-canale-box">
      <button type="button" class="chip-utente switch-canale-btn" aria-haspopup="listbox" aria-expanded="false" title="${L('Cambia canale', 'Switch channel', 'Cambiar canal')}">
        <span class="sc-corrente">${esc(etichetta(corr))}</span>${chevron}
      </button>
      <div class="switch-canale-menu" role="listbox" hidden>
        ${canali.map((c) => `<button type="button" role="option" class="sc-voce${c.canale === attuale ? ' sel' : ''}" data-canale="${esc(c.canale)}" aria-selected="${c.canale === attuale}"><span class="sc-testo">${esc(etichetta(c))}</span><span class="sc-check">${c.canale === attuale ? check : ''}</span></button>`).join('')}
      </div>
    </div>`;
  } else if (stato.ruolo === 'moderatore') {
    centro = `<span class="chip-utente">moderi <strong>@${esc(stato.user.display || attuale)}</strong></span>`;
  }
  const esci = `<a class="btn secondario mini" href="/auth/logout">${L('Esci', 'Log out', 'Salir')}</a>`;
  const tema = toggleTemaHtml();

  const audio = toggleSuonoHtml('mini');
  if (areaUtente) areaUtente.innerHTML = `${selettoreLingua('mini')}${audio}${tema}${centro}${esci}`;

  if (areaMob) areaMob.innerHTML = `<span class="chip-utente">${L('ciao', 'hi', 'hola')}, <strong>${ident}</strong></span>${centro}<div class="drawer-controlli">${selettoreLingua()}${toggleSuonoHtml()}${tema}</div>${esci}`;
  applicaTema();

  document.querySelectorAll('.switch-canale-btn').forEach((btn) =>
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const menu = btn.parentElement.querySelector('.switch-canale-menu');
      const chiuso = menu.hasAttribute('hidden');
      document.querySelectorAll('.switch-canale-menu').forEach((m) => m.setAttribute('hidden', ''));
      document.querySelectorAll('.switch-canale-btn').forEach((b) => b.setAttribute('aria-expanded', 'false'));
      if (chiuso) { menu.removeAttribute('hidden'); btn.setAttribute('aria-expanded', 'true'); }
    }));
  document.querySelectorAll('.sc-voce').forEach((v) =>
    v.addEventListener('click', () => conErrore(async () => {
      const canale = v.dataset.canale;
      v.closest('.switch-canale-menu')?.setAttribute('hidden', '');
      if (canale === attuale) return;
      await api('/api/cambia-canale', { method: 'POST', body: { channel: canale } });
      stato = await api('/api/me'); render();
      toast(L('Ora gestisci @', 'Now managing @', 'Ahora gestionas @') + (stato.user.display || stato.user.login) + (stato.ruolo === 'moderatore' ? L(' come moderatore', ' as moderator', ' como moderador') : L(' come proprietario', ' as owner', ' como propietario')));
    })));
  wireSwitchCanaleGlobale();
}

let _scGlobaleWired = false;
function wireSwitchCanaleGlobale() {
  if (_scGlobaleWired) return; _scGlobaleWired = true;
  const chiudi = () => {
    document.querySelectorAll('.switch-canale-menu').forEach((m) => m.setAttribute('hidden', ''));
    document.querySelectorAll('.switch-canale-btn').forEach((b) => b.setAttribute('aria-expanded', 'false'));
  };
  document.addEventListener('click', (e) => { if (!e.target.closest('.switch-canale-box')) chiudi(); });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') chiudi(); });
}

const LINGUE = ['it', 'en', 'es'];
let LINGUA = (() => {
  const q = new URLSearchParams(location.search).get('lang');
  if (LINGUE.includes(q)) { try { localStorage.setItem('lingua', q); } catch (e) {  } return q; }
  try { const s = localStorage.getItem('lingua'); if (LINGUE.includes(s)) return s; } catch (e) {  }
  const n = (navigator.language || 'it').slice(0, 2).toLowerCase();
  return LINGUE.includes(n) ? n : 'it';
})();
try { document.documentElement.lang = LINGUA; } catch (e) {  }
const L = (it, en, es) => (LINGUA === 'en' ? en : LINGUA === 'es' ? es : it);
function cambiaLingua(l) {
  if (!LINGUE.includes(l) || l === LINGUA) return;
  LINGUA = l;
  try { localStorage.setItem('lingua', l); } catch (e) {  }
  try { document.documentElement.lang = l; } catch (e) {  }
  try { window.SB_CERCA && window.SB_CERCA.invalida(); } catch (e) {  }
  render();
}

function selettoreLingua(cls) {
  return `<div class="lingua-sel${cls ? ' ' + cls : ''}" role="group" aria-label="${L('Lingua', 'Language', 'Idioma')}">${LINGUE.map((l) =>
    `<button type="button" class="lingua-btn${l === LINGUA ? ' on' : ''}" data-lingua="${l}" aria-pressed="${l === LINGUA}">${l.toUpperCase()}</button>`).join('')}</div>`;
}

let TEMA = (() => { try { return localStorage.getItem('tema') || 'auto'; } catch (e) { return 'auto'; } })();
function _sistemaScuro() {
  try { return !!(window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches); } catch (e) { return false; }
}
function temaScuroAttivo() { return TEMA === 'dark' || (TEMA === 'auto' && _sistemaScuro()); }
function applicaTema() {
  const scuro = temaScuroAttivo();
  try { document.documentElement.setAttribute('data-theme', scuro ? 'dark' : 'light'); } catch (e) {  }
  const et = scuro
    ? L('Passa al tema chiaro', 'Switch to light theme', 'Cambiar a tema claro')
    : L('Passa al tema scuro', 'Switch to dark theme', 'Cambiar a tema oscuro');
  document.querySelectorAll('[data-tema-toggle]').forEach((b) => { b.setAttribute('aria-label', et); b.title = et; });

  try {
    if (_mente3dCtrl && typeof _mente3dCtrl.tema === 'function' && document.getElementById('mente3d-canvas')) {
      _mente3dCtrl.tema(scuro);
      if (typeof _menteLegenda === 'function') _menteLegenda(scuro);
    }
  } catch (e) {  }
}
function cambiaTema() {
  TEMA = temaScuroAttivo() ? 'light' : 'dark';
  try { localStorage.setItem('tema', TEMA); } catch (e) {  }
  applicaTema();
}

try {
  const _mq = window.matchMedia('(prefers-color-scheme: dark)');
  const _onSys = () => { if (TEMA === 'auto') applicaTema(); };
  if (_mq.addEventListener) _mq.addEventListener('change', _onSys);
  else if (_mq.addListener) _mq.addListener(_onSys);
} catch (e) {  }

document.addEventListener('click', (e) => {
  const t = e.target.closest && e.target.closest('[data-tema-toggle]');
  if (t) { e.preventDefault(); cambiaTema(); }
});

document.addEventListener('click', (e) => {
  const b = e.target.closest && e.target.closest('[data-lingua]');
  if (b) { e.preventDefault(); cambiaLingua(b.dataset.lingua); }
});

function suonoAcceso() { try { return !!(window.SB_SUONO && window.SB_SUONO.acceso()); } catch (e) { return false; } }
function toggleSuonoHtml(extra) {
  const on = suonoAcceso();
  const acceso = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4z"/><path d="M15.5 8.5a5 5 0 0 1 0 7"/><path d="M18.5 5.5a9 9 0 0 1 0 13"/></svg>';
  const spento = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4z"/><path d="m16 9 5 6M21 9l-5 6"/></svg>';
  const et = on ? L('Suoni accesi', 'Sounds on', 'Sonidos activos') : L('Suoni spenti', 'Sounds off', 'Sonidos apagados');
  return `<button type="button" class="suono-toggle${extra ? ' ' + extra : ''}${on ? ' on' : ''}" data-suono-toggle aria-pressed="${on}" aria-label="${esc(et)}" title="${esc(et)}">${on ? acceso : spento}</button>`;
}
function aggiornaToggleSuono() {
  document.querySelectorAll('[data-suono-toggle]').forEach((b) => {
    const p = b.parentNode; if (!p) return;
    const nuovo = document.createElement('div');
    nuovo.innerHTML = toggleSuonoHtml(b.classList.contains('mini') ? 'mini' : '');
    p.replaceChild(nuovo.firstElementChild, b);
  });
}
document.addEventListener('click', (e) => {
  const t = e.target.closest && e.target.closest('[data-suono-toggle]');
  if (!t) return;
  e.preventDefault();
  const nuovo = !suonoAcceso();
  try { window.SB_SUONO && window.SB_SUONO.imposta(nuovo); } catch (er) {  }
  aggiornaToggleSuono();
  if (nuovo) { try { window.SB_SUONO.suona('conferma'); } catch (er) {  } }
});

function toggleTemaHtml(extra) {
  const sole = '<svg class="ico-sole" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>';
  const luna = '<svg class="ico-luna" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 12.8A8.5 8.5 0 1 1 11.2 3a6.6 6.6 0 0 0 9.8 9.8Z"/></svg>';
  return `<button type="button" class="tema-toggle${extra ? ' ' + extra : ''}" data-tema-toggle>${sole}${luna}</button>`;
}

