    ctx.save(); ctx.shadowColor = 'rgba(0,0,0,.30)'; ctx.shadowBlur = 22; ctx.shadowOffsetY = 6;
    ctx.fillStyle = '#ffffff'; grRoundRect(ctx, cardX, cardY, P, P, 26); ctx.fill(); ctx.restore();
