function _durata(sec) {
  sec = Math.max(0, Math.floor(sec || 0));
  const g = Math.floor(sec / 86400), h = Math.floor((sec % 86400) / 3600);
  const m = Math.floor((sec % 3600) / 60), s = sec % 60;
  if (g) return `${g}g ${h}h`;
  if (h) return `${h}h ${m}m`;
  if (m) return `${m}m ${s}s`;
  return `${s}s`;
}

async function caricaSalute() {
  const box = document.getElementById('salute-box');
  if (!box) return;
  let d;
  try { d = await api('/api/admin/salute'); }
  catch (e) { box.innerHTML = `<p class="vuoto">${L('Errore', 'Error', 'Error')}: ${esc(e.message)}</p>`; return; }
  const mb = (n) => (n / 1048576).toFixed(0) + ' MB';
  const ko = (d.chatKO || []).length;
  box.innerHTML = `
    <p>
      ${d.running ? `<span class="badge verde"><i class="vivo"></i>${L('in esecuzione', 'running', 'en ejecución')}</span>` : `<span class="badge rosso"><i class="spento"></i>${L('fermo', 'stopped', 'detenido')}</span>`}
      &nbsp; <span class="badge">${L('acceso da', 'up for', 'activo desde hace')} ${_durata(d.uptime)}</span>
      &nbsp; <span class="badge viola">${d.streamers} ${L('streamer', 'streamers', 'streamers')}</span>
    </p>
    <p class="spazio-sopra">
      <span class="badge verde">${d.connessi}/${d.canali} ${L('in chat', 'in chat', 'en chat')}</span>
      ${ko ? `&nbsp; <span class="badge rosso">${ko} ${L('scollegati (token)', 'disconnected (token)', 'desconectados (token)')}: ${(d.chatKO || []).map((c) => '#' + esc(c)).join(', ')}</span>` : ''}
      ${d.ascoltando ? `&nbsp; <span class="badge">${d.ascoltando} ${L('in ascolto live', 'live listening', 'escuchando en directo')}</span>` : ''}
    </p>
    <p class="suggerimento spazio-sopra">
      ${L('Database', 'Database', 'Base de datos')}: <strong>${mb(d.dbBytes)}</strong> &nbsp;·&nbsp;
      ${L('Memoria', 'Memory', 'Memoria')}: <strong>${mb(d.rss)}</strong> &nbsp;·&nbsp;
      Node <strong>${esc(d.node || '')}</strong> &nbsp;·&nbsp;
      ${L('Backup', 'Backup', 'Copia')}: <strong>${d.backup?.conteggio || 0}</strong> ${L('copie', 'copies', 'copias')}
    </p>
    <p class="spazio-sopra"><button class="btn secondario mini" id="btn-salute-agg">${_bIco(ICO.grafico)}${L('Aggiorna', 'Refresh', 'Actualizar')}</button></p>`;
  document.getElementById('btn-salute-agg')?.addEventListener('click', () => caricaSalute());
}

async function caricaBackup() {
  const box = document.getElementById('backup-box');
  if (!box) return;
  let d;
  try { d = await api('/api/admin/backup'); }
  catch (e) { box.innerHTML = `<p class="vuoto">${L('Errore', 'Error', 'Error')}: ${esc(e.message)}</p>`; return; }
  const quando = d.ultimo ? new Date(d.ultimo).toLocaleString() : '—';
  const mb = d.bytes ? (d.bytes / 1048576).toFixed(1) + ' MB' : '—';
  box.innerHTML = `
    <p>
      ${d.attivo
        ? `<span class="badge verde"><i class="vivo"></i>${L('attivo', 'active', 'activo')}</span>`
        : `<span class="badge rosso"><i class="spento"></i>${L('disattivato', 'off', 'desactivado')}</span>`}
      &nbsp; <span class="badge viola">${d.conteggio} ${L('copie', 'copies', 'copias')}</span>
      &nbsp; <span class="badge">${L('ultima', 'last', 'última')}: ${esc(quando)}</span>
      &nbsp; <span class="badge">${mb}</span>
    </p>
    <p class="suggerimento">${L('Ogni', 'Every', 'Cada')} <strong>${d.ogniOre}h</strong> · ${L('conservo le ultime', 'I keep the last', 'conservo las últimas')} <strong>${d.tieni}</strong> ${L('copie (le più vecchie si cancellano da sole).', 'copies (older ones auto-delete).', 'copias (las más antiguas se borran solas).')}</p>
    <p class="spazio-sopra"><button class="btn secondario mini" id="btn-backup-ora">${_bIco(ICO.scudo)}${L('Fai un backup ora', 'Back up now', 'Hacer copia ahora')}</button></p>`;
  document.getElementById('btn-backup-ora')?.addEventListener('click', (ev) => conErrore(async () => {
    const b = ev.currentTarget; b.disabled = true;
    const r = await api('/api/admin/backup', { method: 'POST', body: {} });
    if (r.ok) toast(L('Backup eseguito ✓', 'Backup done ✓', 'Copia realizada ✓'));
    else toast((L('Backup fallito: ', 'Backup failed: ', 'Copia fallida: ')) + (r.errore || ''), 'errore');
    caricaBackup();
  }));
}

