async function _chiediPrimaDiUscire() {
  const pan = document.querySelector('.pannello-scheda.visibile');
  const bottoni = _bottoniSalva(pan);
  const r = await chiediScelta({
    titolo: L('Hai modifiche non salvate', 'You have unsaved changes', 'Tienes cambios sin guardar'),
    testo: L('Se esci adesso le perdi.', 'If you leave now you lose them.', 'Si sales ahora las pierdes.'),
    azioni: [
      { id: 'salva', testo: L('Salva ed esci', 'Save and leave', 'Guardar y salir') },
      { id: 'ignora', testo: L('Esci senza salvare', 'Leave without saving', 'Salir sin guardar'), tono: 'secondario' },
      { id: 'resta', testo: L('Resta qui', 'Stay here', 'Quedarme aquí'), tono: 'testo' },
    ],
  });
  if (r === null || r === 'resta') return false;
  if (r === 'salva' && bottoni[0]) {
    bottoni[0].click();
    await new Promise((k) => setTimeout(k, 260));
  }
  azzeraBarraSalva();
  return true;
}

function vaiAScheda(id) {
  if (id !== schedaAttiva && _salvaSporco && !_uscitaInCorso) {
    _uscitaInCorso = true;
    _chiediPrimaDiUscire().then((si) => { _uscitaInCorso = false; if (si) vaiAScheda(id); },
      () => { _uscitaInCorso = false; });
    return;
  }
  morphDa(null);
  const org = (_morphDa && _morphDa.isConnected && _morphDa.dataset.scheda === id
    && !stessaFamiglia(id, schedaAttiva)) ? _morphDa : null;
  _morphDa = null;
  if (id === schedaAttiva) { chiudiMenuTop(); chiudiMenuMobile(); return; }
  schedaAttiva = id;

  try { history.replaceState(null, '', '#' + id); } catch {  }

  const sezioni = [...document.querySelectorAll('.pannello-scheda')].filter((p) => p.dataset.scheda === id);
  if (org && !_menoMoto) morphDa(org);
  const tr = transizione(() => {
    morphDa(null);
    chiudiMenuTop();
    chiudiMenuMobile();
    aggiornaStatoNav(id);
    document.querySelectorAll('.pannello-scheda').forEach((p) =>
      p.classList.toggle('visibile', p.dataset.scheda === id));
    aggiornaTestataPagina();
    armaComparsa();
    sezioni.forEach((p) => { rendiCartePieghevoli(p, id); preparaCarte(p); });
    applicaSottoSchede(id);
  });
  const finita = () => { morphDa(null); avviaComparsa(sezioni); };
  try { tr.finished.then(finita, finita); } catch { finita(); }
  setTimeout(() => morphDa(null), 1600);
  caricaDatiScheda(id);
  azzeraBarraSalva();
  if (DEMO) aggiornaSpiegazioneDemo();
  window.scrollTo({ top: 0, behavior: _menoMoto ? 'auto' : 'smooth' });
}

function initGuscio() {

  document.addEventListener('click', (ev) => {

    const tutte = ev.target.closest('[data-carte]');
    if (tutte) {
      const apri = tutte.dataset.carte === 'apri';
      document.querySelectorAll('.pannello-scheda.visibile .carta.pieghevole')
        .forEach((c) => _piegaCarta(c, apri));
      return;
    }
    const h2 = ev.target.closest('.carta.pieghevole > h2');
    if (!h2) return;

    if (ev.target.closest('a, button, input, select, textarea, label')) return;
    const carta = h2.parentElement;
    _piegaCarta(carta, carta.classList.contains('chiusa'));
  });
  document.addEventListener('keydown', (ev) => {
    if (ev.key !== 'Enter' && ev.key !== ' ') return;
    const h2 = ev.target.closest?.('.carta.pieghevole > h2');
    if (!h2 || h2 !== document.activeElement) return;
    ev.preventDefault();
    const carta = h2.parentElement;
    _piegaCarta(carta, carta.classList.contains('chiusa'));
  });

  document.addEventListener('toggle', (ev) => {
    const d = ev.target;
    if (!d?.dataset?.guida) return;
    try { localStorage.setItem('guida:' + d.dataset.guida, d.open ? '1' : '0'); } catch {  }
  }, true);

  document.getElementById('nav-top')?.addEventListener('click', (ev) => {
    const men = ev.target.closest('[data-menu]');
    if (men) {
      const grp = men.parentElement;
      const era = grp.classList.contains('aperto');
      chiudiMenuTop();
      if (!era) {
        grp.classList.add('aperto');
        men.setAttribute('aria-expanded', 'true');

        const menu = grp.querySelector('.grp-menu');
        if (menu) {
          menu.classList.remove('a-destra');
          if (menu.getBoundingClientRect().right > window.innerWidth - 8) menu.classList.add('a-destra');
        }
      }
      return;
    }
    const b = ev.target.closest('[data-scheda]');
    if (b) vaiAScheda(b.dataset.scheda);
  });

  document.addEventListener('click', (ev) => {
    const sb = ev.target.closest('[data-sblocca]');
    if (sb) { ev.preventDefault(); sbloccaAddon(sb.dataset.sblocca); return; }

    const vp = ev.target.closest('a[data-scheda],button[data-scheda]');
    if (vp && !vp.closest('#nav-drawer')) { ev.preventDefault(); vaiAScheda(vp.dataset.scheda); }
  });

  avviaBarraSalva();

  document.getElementById('barra-giu')?.addEventListener('click', (ev) => {
    if (ev.target.closest('[data-apri-menu]')) {
      const aperto = document.body.classList.toggle('menu-aperto');
      document.getElementById('apri-menu')?.setAttribute('aria-expanded', aperto ? 'true' : 'false');
    }
  });

  document.getElementById('nav-drawer')?.addEventListener('click', (ev) => {
    const b = ev.target.closest('[data-scheda]');
    if (b) vaiAScheda(b.dataset.scheda);
  });

  document.addEventListener('click', (ev) => { if (!ev.target.closest('.grp')) chiudiMenuTop(); });
  document.addEventListener('keydown', (ev) => { if (ev.key === 'Escape') { chiudiMenuTop(); chiudiMenuMobile(); } });

  document.getElementById('apri-menu')?.addEventListener('click', () => {
    const aperto = document.body.classList.toggle('menu-aperto');
    document.getElementById('apri-menu').setAttribute('aria-expanded', aperto ? 'true' : 'false');
  });
  document.getElementById('backdrop')?.addEventListener('click', chiudiMenuMobile);
  document.getElementById('chiudi-menu')?.addEventListener('click', chiudiMenuMobile);

  if (!_menoMoto && window.matchMedia && window.matchMedia('(hover: hover)').matches) {
    let magBtn = null, magCx = 0, magCy = 0, magNoto = false;
    const smagnetizza = (b) => { if (b) { b.style.removeProperty('--mx'); b.style.removeProperty('--my'); } };
    const scorda = () => { magNoto = false; };
    document.addEventListener('pointermove', (ev) => {
      const b = ev.target.closest?.('.btn');
      if (b !== magBtn) { smagnetizza(magBtn); magBtn = b; magNoto = false; }
      if (!b || b.disabled) return;
      if (!magNoto) {
        smagnetizza(b);
        const r = b.getBoundingClientRect();
        if (!r.width) return;
        magCx = r.left + r.width / 2; magCy = r.top + r.height / 2; magNoto = true;
      }
      b.style.setProperty('--mx', ((ev.clientX - magCx) * 0.22).toFixed(1) + 'px');
      b.style.setProperty('--my', ((ev.clientY - magCy) * 0.32).toFixed(1) + 'px');
    }, { passive: true });
    document.addEventListener('pointerdown', () => { smagnetizza(magBtn); scorda(); }, { passive: true });
    window.addEventListener('scroll', scorda, { passive: true, capture: true });
    window.addEventListener('resize', scorda, { passive: true });
  }
}

initGuscio();
caricaStato();

window.SB_APP = {
  get gruppi() { return GRUPPI; },
  get gruppoAdmin() { return GRUPPO_ADMIN; },
  get isAdmin() { return !!(typeof stato !== 'undefined' && stato && stato.isAdmin); },
  get schedaAttiva() { return schedaAttiva; },
  get menoMoto() { return _menoMoto; },
  vai(id) { try { return vaiAScheda(id); } catch (e) { location.hash = '#' + id; } },
  applicaPreset(i) { const t = TEMPLATE_BUILTIN[i]; if (t) applicaTemplate(t.dati); },
  tScheda, tGruppo, L, esc,
  icona(id) { return (typeof ICONA !== 'undefined' && ICONA[id]) || ''; },
  desc(id) { try { const d = DESC[id]; return d ? L(d[0], d[1], d[2]) : ''; } catch (e) { return ''; } },
  schedaValida(id) { try { return schedaValida(id); } catch (e) { return true; } },
  schedaBloccata(id) { try { return schedaBloccata(id); } catch (e) { return false; } },
};
try { window.dispatchEvent(new CustomEvent('sb-app-pronta')); } catch (e) {  }
